// n8n Code node, Run Once for All Items. No network or file access.
const items = $input.all();
if (items.length !== 1) throw new Error('Передайте один маршрут за вызов.');
const f = items[0].json;
const numericKeys = ['origin_latitude', 'origin_longitude', 'destination_latitude', 'destination_longitude'];
for (const key of numericKeys) {
  const limit = key.endsWith('latitude') ? 90 : 180;
  if (typeof f[key] !== 'number' || !Number.isFinite(f[key]) || Math.abs(f[key]) > limit) {
    throw new Error(key + ': требуется числовая координата в допустимом диапазоне. Не угадывайте координаты адреса.');
  }
}
const label = (key) => {
  if (typeof f[key] !== 'string' || !f[key].trim() || f[key].length > 200 || /[\x00-\x1f]/.test(f[key])) {
    throw new Error(key + ': требуется название точки длиной 1–200 символов.');
  }
  return f[key].trim();
};
const coordinates = `${f.origin_longitude},${f.origin_latitude};${f.destination_longitude},${f.destination_latitude}`;
return [{json: {
  origin: {label: label('origin_label'), latitude: f.origin_latitude, longitude: f.origin_longitude},
  destination: {label: label('destination_label'), latitude: f.destination_latitude, longitude: f.destination_longitude},
  url: 'http://172.16.203.45:5000/route/v1/driving/' + coordinates + '?overview=false&steps=false&alternatives=false&radiuses=1000;1000',
}}];

// n8n Code node. Keep OSRM routing failures distinct from an empty lot search.
const request = $('Validate Route Input').first().json;
const response = $input.first().json;
const body = response.body ?? response;
const base = {origin: request.origin, destination: request.destination,
  provider: 'OSRM 26.9.0 / OpenStreetMap', traffic_included: false,
  checked_at_utc: new Date().toISOString()};
if (body.code !== 'Ok') {
  const code = ['NoSegment', 'NoRoute', 'InvalidValue', 'InvalidQuery'].includes(body.code) ? body.code : 'RoutingServiceError';
  return [{json: {...base, ok: false, error_code: code,
    message: code === 'NoSegment' ? 'Не найдена доступная дорога в пределах 1 км от одной из точек. Возможны отсутствие покрытия или неверные координаты.'
      : code === 'NoRoute' ? 'Между точками не найден автомобильный маршрут в загруженном графе.'
      : 'Сервис маршрутизации не вернул корректный ответ. Не подменяйте ошибку оценкой расстояния.',
  }}];
}
const route = body.routes?.[0];
const waypoints = body.waypoints;
if (!route || !Number.isFinite(route.distance) || route.distance < 0 ||
    !Number.isFinite(route.duration) || route.duration < 0 || !Array.isArray(waypoints) ||
    waypoints.length !== 2 || waypoints.some(w => !Number.isFinite(w.distance) || w.distance < 0 || w.distance > 1000)) {
  throw new Error('Некорректный ответ OSRM. Расстояние и время не подтверждены.');
}
const minutes = Math.round(route.duration / 300) * 5;
const hours = Math.floor(minutes / 60);
const time = minutes === 0 && route.duration > 0 ? 'менее 5 мин' : `${hours ? hours + ' ч ' : ''}${minutes % 60} мин`;
const warnings = ['Маршрут рассчитан между привязками координат к дорогам; подъезд к границе участка и законность доступа отдельно не проверены.',
  'Время приблизительное, по скоростям профиля OSRM, без текущих пробок.'];
if (waypoints.some(w => w.distance > 100)) warnings.push('Одна из точек смещена до дороги более чем на 100 м. Уточните фактический автомобильный подъезд.');
return [{json: {...base, ok: true, distance_m: route.distance, duration_s: route.duration,
  distance_km_rounded: Math.round(route.distance / 1000), duration_minutes_rounded: minutes,
  duration_text: time, map_data_timestamp: body.data_version ?? null,
  snapped_points: waypoints.map((w, i) => ({point: i === 0 ? 'origin' : 'destination',
    longitude: w.location[0], latitude: w.location[1], offset_m: Math.round(w.distance * 10) / 10})),
  route_policy: 'OSRM car.lua / MLD; дорожный маршрут, не гарантия минимального расстояния',
  warnings,
}}];
